import json
from books.penwick import *
class T:
    def __init__(s, rs): s.rs=list(rs); s.log=[]
    def send(s,m,p,h,b):
        s.log.append((m,p,h,b)); r=s.rs.pop(0)
        if r is None: raise ConnectionError()
        return r
    def sleep(s,x): s.log.append(('sleep',x))
def R(st,b=None,h=None): return Response(st,h or {},json.dumps(b or {}).encode())
tr={'id':'t1','source':'a','destination':'b','amount':1,'currency':'EUR','reference':'r','status':'reversed'}
t=T([None,R(503,{},{'retry-after':'7'}),R(200,{**tr,'status':'pending'}),R(200,tr)])
print(reverse_transfer(t,'t1')); [print(x) for x in t.log]
t=T([None,R(409,{'error':{'code':'idempotency_in_progress'}},{'Retry-After':'3'}),R(201,tr)])
print(create_transfer(t,'r','a','b',1,'EUR')); [print(x) for x in t.log]
EOF
python /tmp/t.py && python -m unittest 2>&1 | tail -3
